const product = {
  name: '모자',
  price: 19000,
  stock: 7,
};

const price = product.price;

function getPrice() {
  return price;
}

function summarize(product) {
  return {
    name: product.name,
    price: product.price,
    hasStock: product.stock > 0,
  };
}
